def person(x,y):
 return f'<g transform="translate({x} {y})"><g class="pedestrian" id="pedestrian"><g id="feet" fill="#34434c"><ellipse class="foot-left" cx="-4" cy="2" rx="2.4" ry="4"/><ellipse class="foot-right" cx="4" cy="-1" rx="2.4" ry="4"/></g><ellipse cx="-9" cy="0" rx="2.5" ry="3.5" fill="#bf906e"/><ellipse cx="9" cy="0" rx="2.5" ry="3.5" fill="#bf906e"/><path d="M-10-2Q-8-7 0-7Q8-7 10-2L7 5Q0 8-7 5Z" fill="#edaa65"/><ellipse cy="-2" rx="5.8" ry="6.2" fill="#624c41"/><path d="M-3-6Q0-8 3-6" stroke="#806353" stroke-width="1.5" stroke-linecap="round"/><ellipse cy="-8" rx="1.7" ry="1.3" fill="#bf906e"/></g></g>'
CROWD_CSS=''
def crosswalk_crowd():
 global CROWD_CSS
 colors=['#edaa65','#55a79b','#9b87bd','#d87b70','#668cad','#bc965b']
 routes=[[(-22,77),(142,77),(154,13),(251,13),(277,77),(342,77)],[(-22,94),(157,94),(174,31),(236,31),(258,94),(342,94)],[(-22,160),(57,160),(65,229),(153,229),(178,180),(342,180)],[(-22,144),(72,144),(81,210),(139,210),(162,157),(342,157)]]
 parts=[]
 css=[]
 for route,points in enumerate(routes):
  if route%2: points=list(reversed(points))
  lengths=[math.hypot(b[0]-a[0],b[1]-a[1]) for a,b in zip(points,points[1:])]
  total=sum(lengths)
  frames=[]
  elapsed=0
  for j,(x,y) in enumerate(points):
   before=points[max(0,j-1)]; after=points[min(len(points)-1,j+1)]
   angle=math.degrees(math.atan2(after[0]-before[0],-(after[1]-before[1])))
   if j: elapsed+=lengths[j-1]
   pct=elapsed/total*100
   frames.append(f'{pct:.3f}%'+f'{{transform:translate({x}px,{y}px) rotate({angle:.2f}deg)}}')
  css.append(f'.animated .crowd-lane-{route}'+f'{{animation-name:crowd-lane-{route};animation-duration:18s;animation-timing-function:linear;animation-iteration-count:infinite}}@keyframes crowd-lane-{route}'+ '{'+''.join(frames)+'}')
  for i in range(6):
   body=person(0,0).replace('id="pedestrian"',f'id="person-{route}-{i}"').replace('#edaa65',colors[i])
   # Each direction has its own lane; six walkers are evenly spaced along it.
   parts.append(f'<g class="crossing-route crowd-lane-{route}" id="walker-{route}-{i}" style="animation-delay:-{i*3+route*.45}s" transform="translate({25+i*52} {77+route*32}) rotate({-90 if route%2 else 90})"><g transform="scale(.56)">'+body+'</g></g>')
 CROWD_CSS=''.join(css)
 return '<g id="pedestrian-detours">'+''.join(parts)+'</g>'
